<?php if ((int) $this->session->userdata('role_id') === 1): ?><form method="post" action="<?php echo site_url('surat/hapus/' . $surat->id); ?>" onsubmit="return confirm('Hapus surat ini beserta seluruh riwayat dan file?');" class="mt-3"><button type="submit" class="btn btn-danger"><i class="fas fa-trash"></i> Hapus Surat</button></form><?php endif; ?>
<style>.surat-stepper{display:flex;gap:4px;overflow:auto;margin-bottom:24px}.surat-step{min-width:130px;text-align:center;padding:10px 6px;background:#eaecf4;color:#858796;font-size:12px}.surat-step.active{background:#4e73df;color:#fff}.surat-timeline{border-left:3px solid #4e73df;padding-left:20px}.surat-event{position:relative;margin-bottom:20px}.surat-event:before{content:'';position:absolute;left:-29px;top:4px;width:12px;height:12px;border-radius:50%;background:#4e73df}</style>
<div class="container-fluid"><div class="d-flex justify-content-between mb-3"><h1 class="h3 text-gray-800">Tracking Surat</h1><a href="<?php echo site_url('surat'); ?>" class="btn btn-light">Kembali</a></div><div class="card shadow mb-4"><div class="card-body"><h5><?php echo html_escape($surat->perihal); ?></h5><p><?php echo html_escape($surat->tujuan); ?> | <?php echo ucfirst($surat->jenis); ?> | <?php echo html_escape($surat->tanggal_pengajuan); ?></p><span class="badge badge-<?php echo surat_status_class($surat->status); ?> mb-3"><?php echo html_escape($surat->status); ?></span><div class="surat-stepper"><?php $steps=array('Diajukan','Diproses Sekretaris','Sudah Diberi Nomor','Diteruskan ke Direktur','Ditandatangani / Didisposisikan','Selesai'); $active=array_search($surat->status, $steps); if ($active === false) $active=0; foreach ($steps as $idx=>$step): ?><div class="surat-step <?php echo $idx <= $active ? 'active' : ''; ?>"><?php echo $idx+1; ?>. <?php echo $step; ?></div><?php endforeach; ?></div><dl class="row"><dt class="col-sm-3">Nomor Surat</dt><dd class="col-sm-9"><?php echo html_escape($surat->no_surat ?: '-'); ?></dd><dt class="col-sm-3">Dokumen</dt><dd class="col-sm-9"><?php if ($surat->file_draft): ?><a href="<?php echo site_url('surat/download/' . $surat->id . '/draft'); ?>">Draft</a> <?php endif; ?><?php if ($surat->file_ber_nomor): ?><a href="<?php echo site_url('surat/download/' . $surat->id . '/numbered'); ?>">Bernomor</a> <?php endif; ?><?php if ($surat->file_final): ?><a href="<?php echo site_url('surat/download/' . $surat->id . '/final'); ?>">Final</a><?php endif; ?></dd></dl><?php if ($lampiran): ?><h6>Lampiran</h6><ul><?php foreach ($lampiran as $file): ?><li><a href="<?php echo site_url('surat/lampiran/' . $file->id); ?>"><?php echo html_escape($file->nama_file); ?></a></li><?php endforeach; ?></ul><?php endif; ?></div></div><div class="row"><div class="col-lg-7"><div class="card shadow mb-4"><div class="card-header">Riwayat Status</div><div class="card-body surat-timeline"><?php foreach ($logs as $log): ?><div class="surat-event"><strong><?php echo html_escape($log->aksi); ?></strong><div class="small text-muted"><?php echo html_escape($log->user_name ?: 'System'); ?> · <?php echo html_escape($log->created_at); ?></div><div><?php echo html_escape($log->keterangan); ?></div></div><?php endforeach; ?></div></div></div><div class="col-lg-5"><div class="card shadow mb-4"><div class="card-header">Disposisi</div><div class="card-body"><?php if (!$disposisi): ?><span class="text-muted">Belum ada disposisi.</span><?php endif; ?><?php foreach ($disposisi as $item): ?><div class="border-bottom pb-2 mb-2"><strong><?php echo html_escape($item->dari_nama); ?> &rarr; <?php echo html_escape($item->ke_nama ?: $item->ke_bagian); ?></strong><br><?php echo html_escape($item->catatan); ?><br><span class="badge badge-secondary"><?php echo html_escape($item->status); ?></span><?php if ((int) $item->ke_user === (int) $this->session->userdata('id') && $item->status !== 'Selesai'): ?><form method="post" action="<?php echo site_url('surat/disposisi/selesai/' . $item->id); ?>" class="mt-2"><button class="btn btn-sm btn-success">Tandai Selesai</button></form><?php endif; ?></div><?php endforeach; ?></div></div></div></div></div>
